  FT["PH-H4375"] = {"id":"PH-H4375","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5578_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Salug市","en":"An Act Creating Barrio Raba in the Municipality of Salug, Province of Zamboanga Del Norte","orig":"An Act Creating Barrio Raba in the Municipality of Salug, Province of Zamboanga Del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5578","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5578_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4375-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Raba in the Municipality of Salug, Province of Zamboanga del Norte, is hereby converted into a distinct and independent barrio of said municipality, to be known as Barrio Raba. Said barrio shall be bounded as follows:\n1. North—Starting from the corner of Lot No. 2904, thence to Lot No. 2903, 3362, 3363, 3409, 3405, and 3404;\n2. East—following Guisapong Creek until it reaches its source. Thence from its source draw a straight line going south until it reaches the bank of the Mucas River;\n3. South—Mucas River;\n4. West—Starting from corner of Lot No, 2904, thence proceed going Southward, to Lot No. 2900, 2871, 2870, 2869, 2868, 2855, 2854, 285S. Thence draw a straight line until it reaches the bank of Mucas River. All areas within bounds of delineation, comprise the proposed barrio of Raba."}},{"id":"PH-H4375-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p62"};
  FT["PH-H4376"] = {"id":"PH-H4376","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5579_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Salug市","en":"An Act Creating Barrio Sarawagan in the Municipality of Salug, Province of Zamboanga Del Norte","orig":"An Act Creating Barrio Sarawagan in the Municipality of Salug, Province of Zamboanga Del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5579","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5579_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4376-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Sarawagan in Barrio Balakan, Municipality of Salug, Province of Zamboanga del Norte, is separated from said barrio and converted into a distinct and independent barrio of said municipality, to be known as Barrio Sarawagan. The barrio of Sarawagan shall be bounded as follows:\n1. North—Starting from the corner of Lot No. 4014- 4013-2891-4005-3213-3212-3211, 3294-S291-3290-3270 and 3268;\n2. East—Salug River and Guisapong Creek;\n3. South—Starting from corner of Lot 2908, going clockwise proceed to Lot No. 2895, 2907, 2906, 2905, 2904, 2903, 3362, 3363, 3409, 3405, and 3404;\n4. West—Coyong and Sarawagan Creeks."}},{"id":"PH-H4376-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969"}}],"pack":"ph-p62"};
  FT["PH-H4377"] = {"id":"PH-H4377","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5580_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Caba市","en":"An Act Creating Barrio Juan Cartas in the Municipality of Caba, Province of La Union","orig":"An Act Creating Barrio Juan Cartas in the Municipality of Caba, Province of La Union"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 5580","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5580_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4377-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sitio Bas-ang in the Municipality of Caba, Province of La Union, is hereby converted into a distinct and independent barrio of said municipality, to be known as Barrio Juan Cartas."}},{"id":"PH-H4377-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p62"};
