  FT["PH-H4379"] = {"id":"PH-H4379","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5582_1969.html","fetchedAt":"2026-10-06","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"设立Sergio Osmena市","en":"An Act Creating Certain Barrios in the Municipality of Sergio Osmena, Sr., Province of Zamboanga Del Norte","orig":"An Act Creating Certain Barrios in the Municipality of Sergio Osmena, Sr., Province of Zamboanga Del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5582","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 1 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5582_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4379-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Sergio Osmena, Sr., Province of Zamboanga del Norte, are hereby constituted as barrios thereof, to wit:\n1. The sitios of Tanguban, Siasog, Matalom, Napuyan, Dacuyon, Sedimar, and Tulaban are constituted into a distinct and independent barrio of said municipality, to be known as Barrio Willben;\n2. The sitios of Diwakat, Calican, Cabibit, Buburinga, and Solidio are constituted into a distinct and independent barrio of said municipality, to be known as Barrio Antonino; and\n3. The sitios of Upper Buburinga, Lanasan, Bayuhan, Lawaan, and Disoy are constituted into a distinct and independent barrio of said municipality, to be known as Barrio Penacio."}}],"pack":"ph-p62"};
  FT["PH-H4380"] = {"id":"PH-H4380","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5583_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立San Miguel市","en":"An Act Creating Barrio Aglipay in the Municipality of San Miguel, Province of Bohol","orig":"An Act Creating Barrio Aglipay in the Municipality of San Miguel, Province of Bohol"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5583","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5583_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4380-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sitio Aglipay in the Municipality of San Miguel, Province of Bohol, is hereby created and constituted into a barrio to be known as Barrio Aglipay."}},{"id":"PH-H4380-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p62"};
  FT["PH-H4381"] = {"id":"PH-H4381","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5584_1969.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"在奎松省 General Nakar 与 Casiguran 两个市镇分别设立若干新的村社的法案","en":"An Act Creating Certain Barrios in the Municipalities of General Nakar and Casiguran, Province of Quezon","orig":"An Act Creating Certain Barrios in the Municipalities of General Nakar and Casiguran, Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5584","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5584_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4381-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrio Minahan in the Municipality of General Nakar, Province of Quezon, is hereby divided into two distinct and independent barrios, one to be known as Barrio Minahan del Norte and the other as Barrio Minahan del Sur."}},{"id":"PH-H4381-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The boundary between Barrios Minahan del Norte and Minahan del Sur shall be the Binuang Creek, also known as Minahan Creek, that traverses the present Barrio Minahan from west to east."}},{"id":"PH-H4381-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitios of Maigang, Pisa, Mahabang Lalim, Pagsangahan and Lumutan are separated from Barrio Batangan in the same municipality and province, and are hereby converted into distinct and independent barrios to be known as Barrios Maigang, Pisa, Mahabang Lalim, Pagsangahan and Lumutan, respectively."}},{"id":"PH-H4381-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitios of Calabgan and Barrio Site are separated from Barrio Dibet in the Municipality of Casiguran, same province, and are converted into distinct and independent barrios to be known as Barrios of Calabgan and Biyanoan, respectively."}},{"id":"PH-H4381-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitio of Dibacong is hereby separated from Barrio Calangcuasan in the same Municipality of Casiguran, same province, and is converted into a distinct and independent barrio to be known as Barrio Dibacong."}},{"id":"PH-H4381-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sitio of Coso is hereby separated from Barrio Lual in the same municipality and province and is con­verted into a distinct and independent barrio to be known as Barrio Coso."}},{"id":"PH-H4381-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p62","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Certain Barrios in the Municipalities of General Nakar and Casiguran, Province of Quezon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
